css:
.ht2186-container {
    padding: 24px;
    background-color: #f5f3ec;
    color: #22271f;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    font-size: 15px;
    line-height: 1.5;
}
.ht2186-container * { box-sizing: border-box; }
.ht2186-header { background-color: #2f5d3a; color: #f1f4ea; padding: 22px 26px 20px; border-bottom: 4px solid #b5832a; border-radius: 22px 22px 0 0; margin-bottom: 18px; }
.ht2186-eyebrow { font-size: 0.72rem; letter-spacing: 0.14em; text-transform: uppercase; color: #d6e2cf; background-color: #2f5d3a; margin-bottom: 6px; }
.ht2186-header h1 { margin: 0; font-size: 1.7rem; font-weight: 700; color: #f1f4ea; background-color: #2f5d3a; }
.ht2186-sub { margin: 8px 0 0; color: #e2eadb; background-color: #2f5d3a; max-width: 70ch; }
.ht2186-topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
.ht2186-period { font-size: 0.9rem; color: #22271f; background-color: #ffffff; border: 1px solid #d3d0c2; border-radius: 999px; padding: 6px 14px; }
.ht2186-sep { color: #5a5f52; background-color: #ffffff; padding: 0 4px; }
.ht2186-period #roundName { font-weight: 600; }
.ht2186-kpis { display: grid; grid-template-columns: repeat(7, 1fr); gap: 10px; margin-bottom: 18px; }
.ht2186-kpi { background-color: #ffffff; border: 1px solid #d3d0c2; border-radius: 16px; padding: 12px 14px; }
.ht2186-kpi-label { font-size: 0.7rem; letter-spacing: 0.08em; text-transform: uppercase; color: #5a5f52; background-color: #ffffff; min-height: 2.2em; }
.ht2186-kpi-value { font-size: 1.45rem; font-weight: 700; color: #2f5d3a; background-color: #ffffff; line-height: 1.1; margin-top: 4px; font-variant-numeric: tabular-nums; transition: color 0.2s ease; }
.ht2186-kpi-score { color: #2f5d3a; }
.ht2186-kpi-unit { font-size: 0.72rem; color: #5a5f52; background-color: #ffffff; margin-top: 2px; }
.ht2186-briefing { background-color: #ffffff; border: 1px solid #d3d0c2; border-left: 5px solid #b5832a; border-radius: 0 16px 16px 0; padding: 14px 18px; margin-bottom: 16px; }
.ht2186-box-label { font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; color: #2f5d3a; background-color: #ffffff; font-weight: 700; margin-bottom: 6px; }
.ht2186-briefing-text { color: #22271f; background-color: #ffffff; max-width: 80ch; }
.ht2186-panel { background-color: #ffffff; border: 1px solid #d3d0c2; border-radius: 16px; padding: 18px 20px; margin-bottom: 16px; }
.ht2186-panel h2 { margin: 0 0 6px; font-size: 1.15rem; font-weight: 700; color: #2f5d3a; background-color: #ffffff; }
.ht2186-panel-intro { margin: 0 0 14px; color: #3e4438; background-color: #ffffff; max-width: 80ch; }
.ht2186-fields { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.ht2186-field label { display: block; font-size: 0.82rem; font-weight: 600; color: #22271f; background-color: #ffffff; margin-bottom: 4px; }
.ht2186-select { width: 100%; padding: 8px 10px; border: 1px solid #8f927f; border-radius: 10px; background-color: #ffffff; color: #22271f; font-size: 0.9rem; font-family: inherit; }
.ht2186-select option { background-color: #ffffff; color: #22271f; }
.ht2186-select:focus-visible, .ht2186-btn:focus-visible { outline: 3px solid #b5832a; outline-offset: 2px; }
.ht2186-actions { display: flex; justify-content: flex-end; gap: 10px; margin-bottom: 16px; }
.ht2186-btn { border: none; border-radius: 999px; padding: 10px 20px; font-size: 0.92rem; font-weight: 600; cursor: pointer; font-family: inherit; }
.ht2186-btn-primary { background-color: #2f5d3a; color: #ffffff; }
.ht2186-btn-secondary { background-color: #e7e3d6; color: #22271f; }
.ht2186-btn:disabled { opacity: 0.55; cursor: not-allowed; }
.ht2186-result, .ht2186-feedback, .ht2186-chart, .ht2186-history { background-color: #ffffff; border: 1px solid #d3d0c2; border-radius: 16px; padding: 14px 18px; margin-bottom: 16px; }
.ht2186-result-text, .ht2186-feedback-text { color: #22271f; background-color: #ffffff; max-width: 90ch; }
.ht2186-feedback-text.ht2186-warn { border-left: 4px solid #8a3b12; padding-left: 10px; }
.ht2186-reveal { display: block; margin-top: 6px; color: #7a3410; background-color: #ffffff; font-weight: 600; }
.ht2186-chart-wrap { position: relative; height: 220px; }
.ht2186-table-wrap { overflow-x: auto; }
.ht2186-table { width: 100%; border-collapse: collapse; font-size: 0.85rem; font-variant-numeric: tabular-nums; }
.ht2186-table th { text-align: left; color: #22271f; background-color: #ece8dc; padding: 6px 8px; border-bottom: 1px solid #d3d0c2; }
.ht2186-table td { color: #22271f; background-color: #ffffff; padding: 6px 8px; border-bottom: 1px solid #ece8dc; }
.ht2186-cm { text-align: center; color: #22271f; background-color: #ffffff; }
.ht2186-cm-score { font-size: 2.6rem; font-weight: 700; color: #2f5d3a; background-color: #ffffff; }
.ht2186-cm-max { font-size: 1.1rem; color: #5a5f52; background-color: #ffffff; }
.ht2186-cm-verdict { font-size: 1.15rem; font-weight: 700; color: #22271f; background-color: #ffffff; margin-bottom: 10px; }
.ht2186-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin: 10px 0; }
.ht2186-cm-kpi { font-size: 0.8rem; color: #5a5f52; background-color: #f5f3ec; border-radius: 10px; padding: 8px; }
.ht2186-cm-kpi strong { display: block; font-size: 1.05rem; color: #22271f; background-color: #f5f3ec; }
.ht2186-cm-debrief { text-align: left; color: #22271f; background-color: #ffffff; margin: 10px 0; }
.ht2186-cm-insights { text-align: left; color: #22271f; background-color: #ffffff; }
@media (max-width: 900px) { .ht2186-kpis { grid-template-columns: repeat(2, 1fr); } .ht2186-fields { grid-template-columns: 1fr; } .ht2186-cm-kpis { grid-template-columns: repeat(2, 1fr); } }
@media (prefers-reduced-motion: reduce) { .ht2186-container * { transition: none !important; } }

