            return { now: this._clamp(s, 150, 700), pre: this._clamp(pre, 150, 700) };
        }

        _semester(dec, q) {
            var r1 = dec.round1;
            var r2 = (q >= 2) ? dec.round2 : null;
            var r3 = (q >= 3) ? dec.round3 : null;
            var r4 = (q >= 4) ? dec.round4 : null;
            var h = this._herd(dec, q);
            var n = h.n;
            var feed = r3 ? r3.feed : r1.feed;
            var invest2 = r2 ? r2.invest : 'none';
            var renov = (invest2 === 'pasture' && q >= 3);
            var cap = renov ? C.CAPACITY_RENOV : C.CAPACITY;
            var over = Math.max(0, n - cap);
            var y = C.YIELD[feed] + (renov ? C.RENOV_Y : 0);
            y = y * h.mult;
            y = y * (1 - C.OVERGRAZE * over / 10.0);
            var sc = this._scc(dec, q);
            y = y * (1 - C.SCC_LOSS * Math.max(0, (sc.now - 200) / 100.0));
            var liters = n * y * C.DAYS;
            var clinical = 0, lost = 0, residue = false;
            if (q === 3 && r3) {
                var frac = this._clamp(0.04 + 0.0002 * (sc.pre - 200), 0.02, 0.15);
                clinical = frac * n;
                if (r3.resp === 'tank') {
                    residue = true;
                    lost = liters * C.RESIDUE_DAYS / C.DAYS;
                } else {
                    lost = clinical * y * (C.TREAT_DAYS + C.WITHDRAW);
                }
            }
            var sold = Math.max(0, liters - lost);
            var buyer = r2 ? r2.buyer : 'processor';
            var base = C.MILK[q - 1];
            var price, qadj;
            if (buyer === 'crudero') {
                price = base + C.CRUDERO[q - 1];
                qadj = 0;
            } else {
                qadj = this._clamp(0.25 * (350 - sc.now), -60, 40) + (invest2 === 'tank' ? C.TANK_BONUS : 0);
                price = base + qadj + (buyer === 'coop' ? (C.COOP_BONUS - C.COOP_FEE) : 0);
            }
            var revenue = sold * price;
            var excess = 0;
            if (q === 3 && buyer !== 'crudero') {
                excess = Math.max(0, sold - C.QUOTA_REF);
                revenue -= excess * price * (1 - C.QUOTA_PAY[buyer]);
            }
            var concPrice = C.CONC[q - 1];
            if (q <= 3) {
                if (r1.contract === 'forward') { concPrice = C.FWD1; }
                else if (r1.contract === 'half') { concPrice = 0.5 * (concPrice + C.FWD1); }
            } else if (r4 && r4.contract === 'forward') {
                concPrice = C.FWD4;
            }
            var feedCost = n * C.KG[feed] * C.DAYS * concPrice;
            var silage = over * C.SILAGE;
            var health = r2 ? r2.health : 'minimal';
            var fixed = C.FIXED;
            var parl = (invest2 === 'parlour' && q >= 3) || (r4 !== null && r4.invest === 'parlour');
            if (parl && n >= C.PARLOUR_MIN) { fixed -= C.PARLOUR_SAVE; }
            var cost = feedCost + silage + n * C.VARCOW + fixed + h.rear + (r2 ? C.HEALTH_COST[health] : 0);
            if (q === 3 && r3 && r3.resp === 'protocol') { cost += C.PROTOCOL_COST; }
            var capex = 0;
            if (q === 2 && r2) { capex += C.CAPEX[r2.invest]; }
            if (q === 4 && r4) { capex += C.CAPEX[r4.invest]; }
            return {
                q: q, n: n, y: y, liters: liters, sold: sold, price: price, qadj: qadj, scc: sc.now, clinical: clinical, lost: lost,
                residue: residue, excess: excess, concPrice: concPrice, feedCost: feedCost, over: over, revenue: revenue, cost: cost,
                margin: revenue - cost, buy: h.buy, sell: h.sell, capex: capex, rear: h.rear
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            if (r === 1) { return P.herd1[dec.round1.herd] + P.feed1[dec.round1.feed] + P.contract1[dec.round1.contract]; }
            if (r === 2) { return P.invest2[dec.round2.invest] + P.health2[dec.round2.health] + P.buyer2[dec.round2.buyer]; }
            if (r === 3) { return P.herd3[dec.round3.herd] + P.feed3[dec.round3.feed] + P.resp3[dec.round3.resp]; }
            return P.herd4[dec.round4.herd] + P.contract4[dec.round4.contract] + P.invest4[dec.round4.invest];
        }

        _netWorth(dec, s4, cash) {
            var nw = cash - C.CASH0 + (s4.n - C.N0) * C.BOOK;
            var r2 = dec.round2, r4 = dec.round4;
            if (r2) { nw += C.CAPEX[r2.invest] * C.RESIDUAL[r2.invest]; }
            if (r4) {
                nw += C.CAPEX[r4.invest] * C.RESIDUAL[r4.invest];
                if (r4.herd === 'rear') { nw += C.REAR_N * C.HEIFER_V; }
            }
            return nw;
        }

        _verdict(dec, r, s, minCash) {
            if (r === 1) {
                var r1 = dec.round1;
                if (r1.herd === 'buy') { return 'buypeak'; }
                if (r1.contract === 'spot') { return 'unhedged'; }
                if (r1.feed === 'pasture') { return 'underfeed'; }
                return 'ok';
            }
            if (r === 2) {
                var r2 = dec.round2;
                if (r2.invest === 'parlour') { return 'overbuild'; }
                if (r2.buyer === 'crudero') { return 'informal'; }
                if (r2.health === 'minimal') { return 'nohealth'; }
                return 'ok';
            }
            if (r === 3) {
                var r3 = dec.round3;
                if (r3.resp === 'tank') { return 'residue'; }
                if (r3.herd === 'sell') { return 'panic'; }
                if (r3.feed === 'high') { return 'overfeed'; }
                return 'ok';
            }
            var r4 = dec.round4;
            if (minCash < -C.CREDIT_LINE) { return 'squeeze'; }
            if (r4.invest === 'parlour' && s.n < C.PARLOUR_MIN) { return 'idle'; }
            if (r4.contract === 'spot') { return 'unhedged'; }
            return 'ok';
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        _residueCap(ds) {
            return Math.max(C.CAP_FLOOR, C.RESIDUE_CAP - 0.5 * ((ds && ds.residueCases) || 0));
        }

        _liqCap(ds) {
            var mc = (ds && typeof ds.minCash === 'number') ? ds.minCash : C.CASH0;
            return Math.max(C.CAP_FLOOR, C.LIQ_CAP - (-mc - C.CREDIT_LINE) / 5000000);
        }

        _cap(ds) {
            var cap = 100;
            var rc = (ds && ds.residueCases) || 0;
            var mc = (ds && typeof ds.minCash === 'number') ? ds.minCash : C.CASH0;
            if (rc > 0) { cap = Math.min(cap, this._residueCap(ds)); }
            if (mc < -C.CREDIT_LINE) { cap = Math.min(cap, this._liqCap(ds)); }
            return cap;
        }

        _total(ds) {
            var rounds = (ds && ds.rounds) || [];
            var total = 0;
            var i;
            for (i = 0; i < rounds.length; i++) { total += rounds[i].pts; }
            return total;
        }

        _capKey(ds) {
            var total = this._total(ds);
            var cap = this._cap(ds);
            if (total <= cap) { return null; }
            var rc = (ds && ds.residueCases) || 0;
            if (rc > 0 && cap === this._residueCap(ds)) { return 'cap_residue'; }
            return 'cap_liq';
        }

        _composite(ds) {
            var total = Math.min(this._cap(ds), this._total(ds));
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('marginDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.semesters) || [];
                return ss.length ? self._fmtM(ss[ss.length - 1].margin) : '—';
            });
            uiManager.bind('cashDisplay', 'domainState', function(ds) {
                return self._fmtM((ds && typeof ds.cash === 'number') ? ds.cash : C.CASH0);
            });
            uiManager.bind('cowsDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.semesters) || [];
                return ss.length ? String(ss[ss.length - 1].n) : String(C.N0);
            });
            uiManager.bind('yieldDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.semesters) || [];
                return ss.length ? self._fmt1(ss[ss.length - 1].y) : '16.9';
            });
            uiManager.bind('sccDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.semesters) || [];
                return ss.length ? String(Math.round(ss[ss.length - 1].scc)) : String(C.SCC0);
            });
            uiManager.bind('ratioDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.semesters) || [];
                var q = ss.length ? Math.min(ss.length + 1, 4) : 1;
                if (ss.length >= 4) { q = 4; }
                return (Math.round(C.MILK[q - 1] / C.CONC[q - 1] * 100) / 100).toFixed(2);
            });
        }

