            var ds = (state && state.domainState) || {};
            var ss = ds.semesters || [];
            var hist = ds.scoreHistory || [];
            var data = [0, 0, 0, 0];
            var sp = this._t('s_short');
            var i;
            for (i = 0; i < ss.length && i < 4; i++) { data[i] = Math.round(ss[i].margin / 1000000); }
            return {
                marginChart: {
                    labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
