        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ss = ds.semesters || [];
            var hist = ds.scoreHistory || [];
            var dec = ds.dec || {};
            var composite = this._composite(ds);
            var performance = 'Beginner';
            if (composite >= 55) { performance = 'Good'; }
            if (composite >= 75) { performance = 'Excellent'; }
            var last = ss.length ? ss[ss.length - 1] : null;
            var insights = [];
            var r1 = dec.round1 || {};
            var r2 = dec.round2 || {};
            var r3 = dec.round3 || {};
            var r4 = dec.round4 || {};
            insights.push(r1.herd === 'buy' ? this._t('insight_herd_peak') : this._t('insight_herd_ok'));
            insights.push(r3.feed === 'high' ? this._t('insight_feed_high') : this._t('insight_feed_ok'));
            insights.push((r2.invest === 'parlour' || r4.invest === 'parlour') ? this._t('insight_invest_parlour') : this._t('insight_invest_ok'));
            if ((ds.residueCases || 0) > 0) { insights.push(this._t('insight_health_residue')); }
            else if (last && last.scc > 250) { insights.push(this._t('insight_health_weak')); }
            else { insights.push(this._t('insight_health_ok')); }
            insights.push(this._t('insight_next'));
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                cash: ds.cash,
                minCash: ds.minCash,
                netWorth: ds.netWorth,
                scc: last ? Math.round(last.scc) : C.SCC0,
                rounds: hist.length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ht2186-cm">'
